from pathlib import Path
import matplotlib.pyplot as plt
import pandas as pd

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'outputs'
DETAIL = OUT / 'campaign_detail.csv'
SEGMENT = OUT / 'housing_campaign_analysis.csv'

# These CSV files are generated by 04_export_sql_results.py.
detail = pd.read_csv(DETAIL, dtype={'contact_group': str})
segment = pd.read_csv(SEGMENT)

for name, df in [('Q3', detail), ('Q4', segment)]:
    assert df['records'].sum() == 45211, f'{name}: record total mismatch'
    assert df['conversions'].sum() == 5289, f'{name}: conversion total mismatch'
    assert (abs(df['conversion_rate'] - 100 * df['conversions'] / df['records']) < 0.011).all(), f'{name}: rate mismatch'

# Figure 1: subscription rate by exact contact-count band.
order = [str(i) for i in range(1, 11)] + ['11+']
assert set(detail['contact_group']) == set(order) and len(detail) == 11
detail = detail.set_index('contact_group').loc[order].reset_index()
fig, ax = plt.subplots(figsize=(9, 5))
ax.bar(detail['contact_group'], detail['conversion_rate'])
ax.axhline(100 * 5289 / 45211, linestyle='--', label='Overall rate')
ax.set(xlabel='Contacts in campaign', ylabel='Subscription rate (%)',
       title='Subscription rate by contact count')
ax.legend()
fig.tight_layout()
fig.savefig(OUT / 'campaign_detail_rate.png', dpi=160)
plt.close(fig)

# Figure 2: compare housing groups within the same contact band.
bands = ['1_contact', '2_contacts', '3_4_contacts', '5_plus_contacts']
assert len(segment) == 8 and set(segment['housing']) == {'yes', 'no'}
assert not segment.duplicated(['housing', 'contact_band']).any()
pivot = segment.pivot(index='contact_band', columns='housing', values='conversion_rate').loc[bands]
ax = pivot.rename(columns={'no': 'No housing loan', 'yes': 'Has housing loan'}).plot.bar(figsize=(9, 5))
ax.set(xlabel='Contact band', ylabel='Subscription rate (%)',
       title='Housing loan x contact frequency')
ax.tick_params(axis='x', rotation=0)
ax.figure.tight_layout()
ax.figure.savefig(OUT / 'housing_contact_conversion.png', dpi=160)
plt.close(ax.figure)

rate_first = float(detail.loc[detail['contact_group'] == '1', 'conversion_rate'].iloc[0])
rate_last = float(detail.loc[detail['contact_group'] == '11+', 'conversion_rate'].iloc[0])
report = f'''# Bank Marketing: Contact Frequency Analysis

## Data validation
- Records: 45,211; subscriptions: 5,289; overall rate: 11.70%.
- Q3/Q4 outputs reconcile to the same totals.

## Findings
- 1-contact subscription rate: {rate_first:.2f}%.
- 11+-contact subscription rate: {rate_last:.2f}%.
- Within each housing-loan group, observed subscription rates decrease across the four contact-frequency bands.

## Limitations
- Observational associations are not causal effects of adding calls.
- No unique customer identifier is available; these are record-level metrics.
- Contact counts are observed at the end of a campaign and are subject to selection and reverse causality.
'''
(OUT / 'segment_findings.md').write_text(report, encoding='utf-8')
print('Validation passed: 45,211 records / 5,289 subscriptions in both files.')
for name in ['campaign_detail_rate.png', 'housing_contact_conversion.png', 'segment_findings.md']:
    print('Created:', OUT / name)
